import numpy as np
import pytest

from openpilot.starpilot.lateral.lane_led import (Arbiter, Boundary, BoundaryGate, CentreTracker, DelayState, LaneController, LaneLedController, LeverLearner,
                      LaneLedObservation, STATIONS)
from openpilot.starpilot.lateral.lane_led_settings import LaneLedSettings, RANGES, SettingsSlew, problems
from openpilot.starpilot.lateral.tests.lane_led_plant import DT, Road, Scenario, max_step_ratio, run, step_metrics

STRAIGHT = Road([(400.0, 0.0, 0.0)])
R300 = Road([(60.0, 0.0, 1 / 300.0), (300.0, 1 / 300.0, 1 / 300.0), (60.0, 1 / 300.0, 0.0)])
R100 = Road([(40.0, 0.0, 1 / 100.0), (150.0, 1 / 100.0, 1 / 100.0), (40.0, 1 / 100.0, 0.0)])
STEP = -0.30   # car 30 cm left of centre: the controller sees e_y = +0.30 and must turn right


def settings(**kw):
  return LaneLedSettings(**kw)


def lines(y_left=-1.75, y_right=1.75, prob=0.95, std=0.05, x=None):
  x = STATIONS if x is None else x
  return (Boundary(0, "line", x, np.full(len(x), y_left), std, prob),
          Boundary(1, "line", x, np.full(len(x), y_right), std, prob))


# --------------------------------------------------------------------------- sign conventions

def test_sign_convention_offset_turns_toward_centre():
  c = LaneController()
  k = c.update(e_y=0.3, e_psi=0.0, kappa_ff=0.0, speed=18.0, dt=1.0, s=settings(), learn_bias=False, driving=True)
  assert k > 0.0, "centre to the right must request a right turn (positive curvature)"
  c = LaneController()
  k = c.update(e_y=0.0, e_psi=0.05, kappa_ff=0.0, speed=18.0, dt=1.0, s=settings(), learn_bias=False, driving=True)
  assert k > 0.0, "lane heading to the right of the car must request a right turn"


def test_tracker_sign_convention_matches_plant():
  res = run(LaneLedController(), Scenario(STRAIGHT, initial_offset=STEP, duration=1.0, activate_at=5.0))
  late = res["t"] > 0.5
  assert np.allclose(res["e_y"][late], res["e_y_true"][late], atol=0.01)
  assert res["e_y_true"][late].mean() > 0.25


# --------------------------------------------------------------------------- closed-form convergence

def test_closed_form_critically_damped():
  """Pure law, no delay, no limits: e_y follows (1 + w t) e^{-w t} e0."""
  s = settings(max_jerk=1.0, max_added_accel=1.0)
  c = LaneController()
  w = LaneController.omega(s)
  v, dt, e_y, e_psi = 18.0, 0.001, 0.30, 0.0
  errs = []
  for i in range(int(6.0 / dt)):
    t = i * dt
    kappa = c.update(e_y, e_psi, 0.0, v, dt, s, learn_bias=False, driving=True)
    e_psi += v * (0.0 - kappa) * dt
    e_y += v * e_psi * dt
    analytic = 0.30 * (1 + w * t) * math.exp(-w * t)
    errs.append(abs(e_y - analytic))
  assert max(errs) < 0.03
  assert abs(0.30 * (1 + w * 3.0) * math.exp(-w * 3.0)) < 0.10, "recovery_time 3 s must mean within 10 cm at 3 s"


@pytest.mark.parametrize("speed", [8.0, 18.0, 30.0])
def test_plant_step_meets_balanced_acceptance(speed):
  res = run(LaneLedController(), Scenario(STRAIGHT, speed=speed, initial_offset=STEP, duration=12.0))
  engaged = res["t"][res["weight"] > 0.99][0]
  m = step_metrics(res, engaged)
  assert m["settle_s"] <= 3.0, m
  assert m["overshoot_m"] <= 0.05, m
  assert m["sign_changes"] <= 1, m
  assert max_step_ratio(res) <= 1.0 + 1e-6


def test_step_recovery_under_one_hundred_percent_jerk_and_accel():
  res = run(LaneLedController(), Scenario(STRAIGHT, speed=18.0, initial_offset=STEP, duration=8.0))
  v2 = res["speed"] ** 2
  added = (res["kappa_lane"] - res["kappa_model"]) * v2
  assert np.abs(added).max() <= 0.5 + 1e-6


# --------------------------------------------------------------------------- delay prediction

def test_delay_predictor_matches_plant_future():
  """Open loop on a straight road: the predicted error at t must equal the true error at t + delay."""
  delay, tau = 0.33, 0.15
  road = STRAIGHT
  X, Y, psi, idx = road.start(0.0, 0.0)
  from openpilot.starpilot.lateral.tests.lane_led_plant import Car
  car = Car(X, Y, psi, 18.0, delay, tau)
  ds = DelayState()
  truth_t, truth_e = [], []
  preds = []
  for i in range(int(6.0 / DT)):
    t = i * DT
    cmd = 0.0015 * math.sin(2 * math.pi * t / 3.0)
    idx = road.project(car.X, car.Y, idx)
    g = road.frame(car.X, car.Y, car.psi, idx)
    ds.seed(t, car.kappa)
    e_hat, _, _ = ds.predict(t, g["e_y_true"], g["e_psi_true"], car.kappa, 18.0, delay, tau, g["k_road"])
    preds.append((t + delay, e_hat))
    truth_t.append(t); truth_e.append(g["e_y_true"])
    ds.record(t, cmd)
    car.command(t, cmd)
    car.step(t, DT)
  pt = np.array([p[0] for p in preds]); pe = np.array([p[1] for p in preds])
  keep = (pt > 1.0) & (pt < truth_t[-1])
  true_at = np.interp(pt[keep], truth_t, truth_e)
  assert np.abs(true_at).max() > 0.1, "the open-loop excitation must move the car"
  assert np.abs(pe[keep] - true_at).max() < 0.02


@pytest.mark.parametrize("real_delay", [0.15, 0.5])
def test_delay_mismatch_does_not_oscillate(real_delay):
  sc = Scenario(STRAIGHT, speed=25.0, delay=real_delay, assumed_delay=0.33, initial_offset=STEP, duration=12.0)
  res = run(LaneLedController(), sc)
  engaged = res["t"][res["weight"] > 0.99][0]
  m = step_metrics(res, engaged)
  assert m["overshoot_m"] <= 0.05, m
  assert m["sign_changes"] <= 1, m
  assert m["settle_s"] <= 4.0, m


# --------------------------------------------------------------------------- tracker and gate

def test_innovation_limit_spreads_a_jump():
  s = settings()
  tr = CentreTracker()
  for _ in range(10):
    tr.observe(*lines(), 0.05, s)
  assert abs(tr.centre_at(0.0)) < 0.01
  moves = []
  for _ in range(12):
    before = tr.centre_at(0.0)
    tr.observe(*lines(y_left=-1.45, y_right=2.05), 0.05, s)   # centre jumps 30 cm right
    tr.apply_pending(0.05)                                      # the frame's innovation lands over the frame period
    moves.append(tr.centre_at(0.0) - before)
  assert max(moves) <= s.innovation_limit_m + 1e-9
  assert tr.centre_at(0.0) > 0.25, "a real shift still arrives within a few frames"


def test_gate_hysteresis_ignores_flicker():
  s = settings(switch_hold=0.25)                   # the frame counts below assume a 0.25 s hold
  g = BoundaryGate()
  left, right = lines()
  for _ in range(10):
    g.update((left, right), 0.05, s)
  assert g.selected() == (left, right)
  weak = Boundary(0, "line", STATIONS, left.y, 0.05, 0.05)
  for frame in range(4):                          # 0.2 s below drop threshold, under the 0.25 s hold
    g.update((weak, right), 0.05, s)
    assert g.selected()[0] is weak, "still adopted; boundary object is simply the latest sample"
  g.update((left, right), 0.05, s)
  assert g.selected() == (left, right)
  for _ in range(6):
    g.update((weak, right), 0.05, s)
  assert g.selected()[0] is None, "sustained loss drops the boundary"


def test_source_switch_to_edge_has_no_step():
  sc = Scenario(R300, speed=18.0, switch_left_to_edge_at=6.0, duration=12.0)
  res = run(LaneLedController(), sc)
  assert max_step_ratio(res) <= 1.0 + 1e-6
  after = res["t"] > 6.5
  assert (res["state"][after] == "lane_led").all()
  assert (res["mode"][after] == "one_right").all(), "the edge never defines the centre; the right line's guard curve carries the heading"
  assert np.abs(res["e_y_true"][after]).max() < 0.10, "losing the left line must not move the car: the model's path is the lateral reference"


def test_one_line_follows_the_model_laterally_and_the_line_in_heading():
  """Change 25: with one line there is no remembered width. The lateral target is the model's path relative to the
  line's guard curve; the model aims 0.3 m toward +y here and the car goes there, lane-led, without a step."""
  sc = Scenario(STRAIGHT, speed=18.0, one_line_from=5.0, model_offset=0.3, duration=16.0)
  res = run(LaneLedController(), sc)
  at7 = (res["t"] > 6.5) & (res["t"] < 8.0)
  assert (res["mode"][at7] == "one_left").all() and (res["state"][at7] == "lane_led").all()
  late = res["t"] > 13.0
  assert (res["state"][late] == "lane_led").all()
  assert abs(np.mean(res["e_y_true"][late]) + 0.3) < 0.06, "the car sits where the model's path is (centre reads -0.3)"
  assert max_step_ratio(res) <= 1.0 + 1e-6


def test_one_line_guard_keeps_the_clearance():
  """The model hugs: it wants to be 0.45 m toward the only line (3.5 m lane: 1.3 m from it). With the lane width seen
  on the two-line stretch before, the guard holds the car at car_width / 2 + line_clearance = 1.525 m from the line,
  i.e. 0.225 m from the centre. With no width ever seen, the cap falls back to min_width (2.5 m) and holds 1.475 m.
  A model path much closer to the line is an obstacle, not a hug: the model wins (next test)."""
  sc = Scenario(STRAIGHT, speed=18.0, one_line_from=5.0, model_offset=-0.45, duration=18.0)
  res = run(LaneLedController(), sc)
  late = res["t"] > 14.0
  assert (res["state"][late] == "lane_led").all()
  assert abs(np.mean(res["e_y_true"][late]) - 0.225) < 0.05, np.mean(res["e_y_true"][late])
  assert max_step_ratio(res) <= 1.0 + 1e-6
  sc2 = Scenario(STRAIGHT, speed=18.0, one_line_from=5.0, model_offset=-0.2, duration=18.0)   # a smaller hug: inside the guard's say
  res2 = run(LaneLedController(settings(line_clearance=0.9)), sc2)
  assert abs(np.mean(res2["e_y_true"][res2["t"] > 14.0]) + 0.075) < 0.05, "a wider clearance moves the guard (car must sit 0.075 past centre)"
  res3 = run(LaneLedController(), Scenario(STRAIGHT, speed=18.0, one_line_from=0.0, model_offset=-0.45, duration=16.0))
  assert abs(np.mean(res3["e_y_true"][res3["t"] > 12.0]) - 0.225) < 0.05, "no width ever seen: the model-implied width (2.6 m) allows the full clearance"


def test_one_line_model_swerve_toward_the_line_wins_over_the_guard():
  """A parked car on the kerb side: the model's path moves 0.9 m toward the only line, far beyond what the guard would
  allow. That is an obstacle the lines cannot see, so the divergence veto hands to the model instead of the guard
  holding the car on the parked car's side."""
  res = run(LaneLedController(), Scenario(STRAIGHT, speed=18.0, one_line_from=5.0, model_offset=-0.9, duration=14.0))
  late = res["t"] > 9.0
  assert (res["state"][late] == "model_led").all() and (res["reason"][late] == "model_divergence").all()
  assert max_step_ratio(res) <= 1.0 + 1e-6


def test_narrow_lane_guards_never_push_over_the_other_line():
  """A 2.3 m lane, narrower than the 2.5 m a pair needs, so the pair is rejected and the car drives from one line with
  both guards. The corridor is inverted (car plus two clearances is 3.05 m), so the target is the middle: centred.
  With only one line seen from the start, the guard distance is capped by the lane width the model's path implies, so
  the far side (0.925 m from the centre of the car) stays inside the 2.3 m lane instead of 15 cm over its unseen line."""
  both = run(LaneLedController(), Scenario(STRAIGHT, speed=15.0, width=2.3, duration=14.0))
  late = both["t"] > 10.0
  assert (both["mode"][late] != "two").all(), "a 2.3 m pair is not accepted as a lane"
  assert np.abs(np.mean(both["e_y_true"][late])) < 0.05, np.mean(both["e_y_true"][late])
  one = run(LaneLedController(), Scenario(STRAIGHT, speed=15.0, width=2.3, one_line_from=4.0, edge_offset=5.0, right_edge_offset=5.0, duration=14.0))
  e = np.mean(one["e_y_true"][one["t"] > 10.0])
  # the car's centre sits at -e from the lane centre; its far (right) side must stay inside the right line at +1.15
  assert -e + 0.925 <= 1.15 + 0.02, (e, "far side over the unseen line")
  assert e > -0.30, (e, "and the guard still holds the car off the seen line by what the lane allows")
  assert max_step_ratio(one) <= 1.0 + 1e-6


def test_edge_guard_pushes_off_a_road_edge_only_when_enabled():
  """Two lines, but the left road edge sits 0.5 m inside the left line (1.25 m from centre). With the edge guard the
  car is held car_width / 2 + edge_clearance = 1.425 m from it, 0.175 m right of centre; without it, centred."""
  sc = Scenario(STRAIGHT, speed=18.0, edge_offset=-0.5, duration=16.0)
  on = run(LaneLedController(), sc)
  off = run(LaneLedController(settings(edge_guard=False)), sc)
  late = on["t"] > 12.0
  assert abs(np.mean(on["e_y_true"][late]) + 0.175) < 0.05, np.mean(on["e_y_true"][late])
  assert abs(np.mean(off["e_y_true"][late])) < 0.03
  assert (on["state"][late] == "lane_led").all() and max_step_ratio(on) <= 1.0 + 1e-6


# --------------------------------------------------------------------------- arbiter

def test_arbiter_slews_and_never_steps():
  s = settings(fade_in=1.0)                        # the 0.5 s weight check below assumes a 1 s fade
  a = Arbiter()
  out = [a.update(0.002, 0.0, 1.0, False, 18.0, 0.01, s) for _ in range(150)]
  ws = [o[1] for o in out]; ks = [o[0] for o in out]
  assert abs(ws[99] - 1.0) < 1e-6 and ws[49] < 0.6
  assert max(np.diff(ws)) <= 0.01 / s.fade_in + 1e-9
  step = s.max_jerk / 18.0 ** 2 * 0.01
  assert np.abs(np.diff(ks)).max() <= step + 1e-12, "a 0.002 gap is handed over at the jerk budget, not at the fade rate"
  assert abs(ks[-1] - 0.002) < 1e-9, "and the hand-over completes"
  out2 = [a.update(0.002, 0.0, 1.0, True, 18.0, 0.01, s) for _ in range(200)]
  ws2 = [o[1] for o in out2]; ks2 = [o[0] for o in out2]
  assert ws2[-1] == 0.0 and min(np.diff(ws2)) >= -0.01 / s.fade_out - 1e-9
  assert np.abs(np.diff(ks2)).max() <= step + 1e-12 and abs(ks2[-1]) < 1e-9


def test_lane_change_hands_back_and_returns():
  sc = Scenario(STRAIGHT, speed=18.0, lane_changes=((5.0, 7.0),), duration=12.0)
  res = run(LaneLedController(), sc)
  assert (res["state"][(res["t"] > 5.6) & (res["t"] < 7.0)] == "model_led").all()
  assert (res["reason"][(res["t"] > 5.0) & (res["t"] < 7.0)] == "lane_change").all()
  assert (res["state"][res["t"] > 8.5] == "lane_led").all()
  assert max_step_ratio(res) <= 1.0 + 1e-6


def test_model_divergence_vetoes():
  """The model's path leaves the lane (a junction): the lane controller must hand back."""
  sc = Scenario(STRAIGHT, speed=18.0, model_offset=1.5, duration=4.0)
  res = run(LaneLedController(), sc)
  assert (res["reason"][res["t"] > 1.0] == "model_divergence").all()
  assert (res["state"][res["t"] > 1.0] == "model_led").all()


# --------------------------------------------------------------------------- bias and disturbances

def test_steady_bend_centred_with_camera_ahead_of_axle():
  """The camera sees the lane heading 1.5 m ahead of the axle the car turns about. In a steady bend that heading
  reads lever * kappa even when the car is perfectly concentric; a controller that damps it parks the car inside the
  bend by 2 * damping * v * lever * kappa / omega (the second v8 road drive: 12 cm at R 345, 17 m/s). Telling the
  controller the lever removes it."""
  sc = Scenario(R300, speed=18.0, camera_lead=1.5, duration=24.0)
  steady = lambda res: (res["t"] > 12.0) & (res["t"] < 20.0)      # inside the 300 m arc
  naive = run(LaneLedController(settings(axle_to_camera_m=0.0, lever_learn=False)), sc)
  assert np.mean(naive["e_y_true"][steady(naive)]) < -0.08, "the unaware controller sits well inside a left bend"
  fixed = run(LaneLedController(), sc)
  assert abs(np.mean(fixed["e_y_true"][steady(fixed)])) < 0.03
  assert (fixed["state"][fixed["t"] > 4.0] == "lane_led").all()
  assert max_step_ratio(fixed) <= 1.0 + 1e-6


WINDING = Road([(60, 0, 1 / 300), (300, 1 / 300, 1 / 300), (60, 1 / 300, 0), (150, 0, 0),
                (60, 0, -1 / 250), (250, -1 / 250, -1 / 250), (60, -1 / 250, 0), (150, 0, 0),
                (60, 0, 1 / 400), (400, 1 / 400, 1 / 400), (60, 1 / 400, 0), (150, 0, 0),
                (60, 0, -1 / 350), (350, -1 / 350, -1 / 350), (60, -1 / 350, 0)])
WINDING_LEN = 100.0 + 2430.0 + 50.0


def _bend_centring(res):
  m = (np.abs(res["k_road"]) > 1 / 500.0) & (res["state"] == "lane_led")
  return float(np.mean(res["e_y_true"][m])), float(np.percentile(np.abs(res["e_y_true"][m]), 95))


def test_lever_learner_finds_the_camera_from_steady_bends():
  """Camera 2.0 m ahead, slider says 1.0: the learner moves the lever toward 2.0 from steady bends of both hands and
  the bend centring improves with it. Change 23 in the README. Three passes of the winding road are about a drive's
  worth of steady bends; the prior is worth a minute of R 300, so the estimate is most of the way after that."""
  sc = Scenario(WINDING, speed=18.0, camera_lead=2.0, duration=WINDING_LEN / 18.0)
  ctrl = LaneLedController(settings(axle_to_camera_m=1.0, lever_learn=True))
  levers, p95s = [], []
  for _ in range(3):
    res = run(ctrl, sc)
    levers.append(ctrl.lever_learner.lever(18.0, 1.0)); p95s.append(_bend_centring(res)[1])
    assert max_step_ratio(res) <= 1.0 + 1e-6
  assert levers[0] > 1.4 and levers[1] > levers[0] and levers[2] > levers[1], levers
  assert 1.75 <= levers[2] <= 2.15, levers
  assert ctrl.lever_learner.theta(1.0)[2] == pytest.approx(0.0, abs=2e-4), "one speed teaches no speed term"
  assert p95s[2] < 0.75 * p95s[0], (p95s, "bend |e_y| p95 falls as the lever is learned")
  assert abs(_bend_centring(res)[0]) < 0.02
  fixed = run(LaneLedController(settings(axle_to_camera_m=1.0, lever_learn=False)), sc)
  assert p95s[2] < 0.75 * _bend_centring(fixed)[1], "and beats the wrong constant"


def test_lever_learner_off_uses_the_slider():
  sc = Scenario(WINDING, speed=18.0, camera_lead=2.0, duration=40.0)
  ctrl = LaneLedController(settings(axle_to_camera_m=1.0, lever_learn=False))
  res = run(ctrl, sc)
  assert ctrl.lever_learner.n == 0 and ctrl.lever_learner.accepted == 0
  assert np.all(res["lever"] == 1.0)
  assert res["lever_n"][-1] == 0


def test_lever_learner_speed_term_from_rear_slip():
  """With rear slip the body points into the bend more at higher lateral acceleration, so the effective lever falls
  with speed (the road: 1.9 m at 12 m/s, 1.2 at 20). Driving the same bends at 12 and 22 m/s teaches the speed
  term; the sign and size come out right and the lever at each speed lands near the truth."""
  ctrl = LaneLedController(settings(axle_to_camera_m=1.5, lever_learn=True))
  truth = lambda v: 2.3 - 0.0027 * v * v
  for _ in range(2):
    for v in (12.0, 22.0):
      run(ctrl, Scenario(WINDING, speed=v, camera_lead=2.3, slip_gain=0.0027, duration=WINDING_LEN / v))
  th = ctrl.lever_learner.theta(1.5)
  assert th[2] < -0.0012, th
  l12, l22 = ctrl.lever_learner.lever(12.0, 1.5), ctrl.lever_learner.lever(22.0, 1.5)
  assert l12 - l22 > 0.5, (l12, l22)
  assert abs(l12 - truth(12.0)) < 0.15 and abs(l22 - truth(22.0)) < 0.35, (l12, l22, truth(12.0), truth(22.0))


def test_lever_learner_state_round_trip_and_rejects_rubbish():
  a = LeverLearner()
  for k in range(500):
    a.observe(0.0063 + 0.0002 * math.sin(k), 1 / 300.0, 18.0)
  b = LeverLearner()
  assert b.load(json.loads(json.dumps(a.state())))
  assert b.lever(18.0, 1.5) == pytest.approx(a.lever(18.0, 1.5)) and b.n == pytest.approx(a.n) and b.accepted == a.accepted
  c = LeverLearner()
  assert not c.load({"A": [[1, 2], [3, 4]], "b": [0, 0, 0], "n": 1})
  assert not c.load({"A": np.full((3, 3), np.nan).tolist(), "b": [0, 0, 0], "n": 1})
  assert not c.load("nonsense") and not c.load(None)
  assert c.n == 0 and c.lever(18.0, 1.5) == 1.5
  # the prior is the slider: with no data the lever is the slider at every speed; bounded whatever the data says
  assert a.lever(30.0, 1.5) <= 3.0 and LeverLearner().lever(30.0, 2.2) == 2.2
  d = LeverLearner()
  for _ in range(20000):
    d.observe(0.05, 1 / 100.0, 10.0)      # 5 m of lever: clipped to the range
  assert d.lever(10.0, 1.5) <= 3.0


def test_lever_toggle_mid_drive_has_no_step():
  """Switching learning off (or on) mid-drive moves the lever in use at a bounded rate, through the same loop that
  showed no step for slider changes."""
  sc = Scenario(R300, speed=18.0, camera_lead=2.0, duration=30.0)
  ctrl = LaneLedController(settings(axle_to_camera_m=1.0, lever_learn=True))
  run(ctrl, Scenario(WINDING, speed=18.0, camera_lead=2.0, duration=WINDING_LEN / 18.0))
  learned = ctrl.lever_learner.lever(18.0, 1.0)
  assert learned > 1.3
  flipped = {"done": False}
  orig = ctrl.update

  def update(obs):
    if obs.t > 14.0 and not flipped["done"]:
      ctrl.set_settings(settings(axle_to_camera_m=1.0, lever_learn=False)); flipped["done"] = True
    return orig(obs)
  ctrl.update = update
  res = run(ctrl, sc)
  assert max_step_ratio(res) <= 1.0 + 1e-6
  lever = res["lever"]
  assert abs(lever[-1] - 1.0) < 1e-6 and abs(np.diff(lever)).max() <= 0.2 * DT + 1e-9


def test_bias_removes_steady_lean():
  sc = Scenario(R300, speed=18.0, disturbance=0.0003, duration=45.0)
  off = run(LaneLedController(settings(bias_enabled=False)), sc)
  on = run(LaneLedController(settings(bias_enabled=True)), sc)
  assert abs(off["e_y_true"][-1]) > 0.05, "without bias learning a 0.13 m/s2 lean leaves a steady offset"
  assert abs(on["e_y_true"][-1]) < 0.02
  assert abs(on["bias"][-1] + 0.0003) < 0.0001


def test_hold_through_short_gap_keeps_driving():
  sc = Scenario(R300, speed=18.0, dropouts=((8.0, 8.3),), model_lean=0.0008, duration=14.0)
  res = run(LaneLedController(), sc)
  assert max_step_ratio(res) <= 1.0 + 1e-6
  during = (res["t"] >= 8.0) & (res["t"] < 8.3)
  assert res["weight"][during].min() > 0.8, "a gap shorter than the hold keeps the lane controller driving"
  assert np.abs(res["e_y_true"][res["t"] > 9.5]).max() < 0.10
  assert "holding_through_gap" in set(res["reason"][during])


def test_long_gap_fades_to_model_and_back():
  sc = Scenario(R300, speed=18.0, dropouts=((8.0, 10.0),), duration=15.0)
  res = run(LaneLedController(), sc)
  assert max_step_ratio(res) <= 1.0 + 1e-6
  assert (res["state"][(res["t"] > 9.2) & (res["t"] < 10.0)] == "model_led").all()
  assert (res["state"][res["t"] > 12.0] == "lane_led").all()


def test_noisy_lines_stay_smooth():
  sc = Scenario(R300, speed=18.0, noise=0.05, model_lean=0.0008, duration=15.0, seed=3)
  res = run(LaneLedController(), sc)
  late = res["t"] > 5.0
  assert (res["state"][late] == "lane_led").mean() > 0.95
  assert np.abs(res["e_y_true"][late]).max() < 0.12
  assert max_step_ratio(res) <= 1.0 + 1e-6
  v2 = res["speed"][late] ** 2
  assert np.percentile(np.abs(np.diff(res["candidate"][late])) * v2[1:] / DT, 99) < 0.40, "not living on the jerk limit (0.5)"


def test_bend_entry_r100_tracks():
  """The plant's model leans 0.14 m/s2 toward the outside, so only a lane-led controller keeps the centre."""
  res = run(LaneLedController(), Scenario(R100, speed=12.0, model_lean=-0.001, duration=20.0))
  late = res["t"] > 4.0
  assert (res["state"][late] == "lane_led").all(), set(res["reason"][late])
  assert np.abs(res["e_y_true"][late]).max() < 0.15
  assert max_step_ratio(res) <= 1.0 + 1e-6


# --------------------------------------------------------------------------- settings

def test_settings_validation():
  assert not problems(settings())
  assert problems(settings(recovery_time=0.1))
  assert problems(settings(drop_confidence=0.5, adopt_confidence=0.4))
  for name, (lo, hi) in RANGES.items():
    assert not problems(settings(**{name: lo})) or name in ("min_width", "max_width", "drop_confidence", "adopt_confidence")


def test_settings_slew_takes_slew_time():
  sl = SettingsSlew(settings(recovery_time=3.0))
  target = settings(recovery_time=5.0, bias_enabled=False)
  eff = sl.update(target, 0.01)
  assert eff.bias_enabled is False, "booleans switch at once"
  assert abs(eff.recovery_time - 3.01) < 1e-6, "numbers move linearly over slew_time"
  for _ in range(250):
    eff = sl.update(target, 0.01)
  assert eff.recovery_time == 5.0 and sl.settled()


def test_slider_change_mid_drive_has_no_step():
  ctrl = LaneLedController()
  sc = Scenario(R300, speed=18.0, duration=12.0)
  # Change the tune at 6 s by swapping the saved settings through the controller's own hook.
  rng_res = {}

  def speed_fn(t):
    if 5.99 < t < 6.01 and "done" not in rng_res:
      ctrl.set_settings(settings(recovery_time=1.5, offset_m=0.2, max_added_accel=1.0))
      rng_res["done"] = True
    return 18.0
  sc.speed_fn = speed_fn
  res = run(ctrl, sc)
  assert max_step_ratio(res) <= 1.0 + 1e-6
  assert abs(res["e_y_true"][-1] + 0.2) < 0.05, "new offset reached: +y is right on the car, a positive offset moves the car to +y, so the centre reads -0.2"


# --------------------------------------------------------------------------- fuzz: no step, ever

def test_no_step_fuzz():
  minutes = float(os.environ.get("LANE_LED_FUZZ_MINUTES", "10"))
  rng = np.random.default_rng(42)
  road = Road([(200.0, 0.0, 1 / 400.0), (300.0, 1 / 400.0, -1 / 250.0), (300.0, -1 / 250.0, 0.0), (400.0, 0.0, 0.0),
               (200.0, 0.0, 1 / 150.0), (200.0, 1 / 150.0, 0.0)] * 6)
  duration = minutes * 60.0
  per_min = lambda n: max(1, int(round(n * minutes / 10.0)))   # event counts are specified for a 10-minute run
  dropouts = tuple((t, t + rng.uniform(0.05, 1.5)) for t in np.sort(rng.uniform(5, duration - 5, per_min(60))))
  stale = tuple((t, t + rng.uniform(0.03, 0.4)) for t in np.sort(rng.uniform(5, duration - 5, per_min(80))))
  lane_changes = tuple((t, t + rng.uniform(1.0, 4.0)) for t in np.sort(rng.uniform(5, duration - 5, per_min(12))))
  ctrl = LaneLedController()
  changes = {float(t): None for t in np.sort(rng.uniform(5, duration - 5, per_min(20)))}
  numeric = [n for n in RANGES if n not in ("min_width", "max_width", "slew_time", "tau_steer", "min_speed", "max_lateral_accel")]

  def speed_fn(t):
    for ct in list(changes):
      if ct <= t < ct + 0.011:
        kw = {}
        for name in rng.choice(numeric, 3, replace=False):
          lo, hi = RANGES[name]
          kw[name] = float(rng.uniform(lo, hi))
        if "drop_confidence" in kw or "adopt_confidence" in kw:
          kw["drop_confidence"], kw["adopt_confidence"] = 0.15, 0.30
        ctrl.set_settings(settings(**kw))
        del changes[ct]
    return 13.0 + 6.0 * math.sin(2 * math.pi * t / 90.0)   # at most 19 m/s: the R150 bends stay under 2.5 m/s2
  sc = Scenario(road, speed=18.0, noise=0.03, dropouts=dropouts, stale=stale, lane_changes=lane_changes,
                switch_left_to_edge_at=duration / 2, switch_left_to_edge_until=duration / 2 + 15.0,
                duration=duration, speed_fn=speed_fn, seed=7)
  res = run(ctrl, sc)
  assert np.isfinite(res["candidate"]).all()
  assert max_step_ratio(res) <= 1.0 + 1e-6
  assert set(res["state"]) <= {"lane_led", "blended", "model_led"}
  # Every injected dropout or lane change costs its own duration plus hold, re-adoption and fade-in (about 2.5 s).
  unavailable = sum(b - a + 2.5 for a, b in dropouts) + sum(b - a + 2.5 for a, b in lane_changes) + 1.5
  expected = max(0.0, 1.0 - unavailable / duration)
  assert (res["state"] == "lane_led").mean() > expected - 0.10, (expected, (res["state"] == "lane_led").mean())
  assert np.abs(res["e_y_true"]).max() < 0.6


def test_blind_sharp_turn_while_inactive_does_not_poison_the_track():
  """Road finding, 1 Nov: during a manual sharp turn with no usable lines the propagated curve blew up to kilometres
  and the 5 cm innovation limit then kept it from ever recovering, so the next engaged stretch was handed to the model."""
  ctrl = LaneLedController()
  s = settings()
  # warm up on a straight with two lines, lateral active
  t = 0.0
  for i in range(100):
    ctrl.update(LaneLedObservation(t=t, speed=10.0, measured_curvature=0.0, model_curvature=0.0, delay=0.33,
                                   boundaries=lines(), model_sample_id=1 + i // 5))
    t += 0.01
  assert abs(ctrl.tracker.centre_at(0.0)) < 0.02
  # lateral inactive, a 0.1 1/m turn (10 m radius) for 3 s with no usable lines at all
  for i in range(300):
    ctrl.update(LaneLedObservation(t=t, speed=4.0, measured_curvature=0.1, model_curvature=0.1, delay=0.33,
                                   boundaries=(), model_sample_id=100 + i // 5, lateral_active=False))
    t += 0.01
  assert not ctrl.tracker.lost() and abs(ctrl.tracker.centre_at(0.0)) < 3.0, "the blind track must have been cleared, not left to blow up"
  # lines return and lateral engages: lane-led again within the fade-in, with a sane centre
  r = None
  for i in range(200):
    r = ctrl.update(LaneLedObservation(t=t, speed=10.0, measured_curvature=0.0, model_curvature=0.0, delay=0.33,
                                       boundaries=lines(), model_sample_id=1000 + i // 5))
    t += 0.01
  assert abs(r.e_y) < 0.05 and r.state == "lane_led", (r.e_y, r.state, r.reason)


def test_lost_track_snaps_to_the_observation():
  s = settings()
  tr = CentreTracker()
  for _ in range(10):
    tr.observe(*lines(), 0.05, s); tr.apply_pending(0.05)
  tr.c[0] += 2.5                                 # the track has drifted 2.5 m away from where the lines are
  tr.observe(*lines(), 0.05, s); tr.apply_pending(0.05)
  assert abs(tr.centre_at(0.0)) < 0.05, "an observation a metre or more from the track re-acquires it in one frame"


# --------------------------------------------------------------------------- compute

def test_update_is_cheap_on_pc():
  ctrl = LaneLedController()
  sc = Scenario(R300, speed=18.0, duration=2.0)
  run(ctrl, sc)
  obs = LaneLedObservation(t=100.0, speed=18.0, measured_curvature=0.003, model_curvature=0.003, delay=0.33,
                           boundaries=lines(), model_sample_id=1)
  t0 = time.perf_counter()
  for i in range(2000):
    ctrl.update(LaneLedObservation(**{**obs.__dict__, "t": 100.0 + i * 0.01, "model_sample_id": 1 + i // 5}))
  per = (time.perf_counter() - t0) / 2000
  assert per < 0.002, f"{per * 1e3:.2f} ms per update on the PC; device budget is p99 under 8 ms"
